<script setup lang="ts">
import FormField from '@/components/FormField.vue'
const props=withDefaults(defineProps<{modelValue?:any;label:string;type?:string;hint?:string;error?:string;required?:boolean;disabled?:boolean;options?:{value:string;label:string}[];maximum?:number}>(),{type:'text',options:()=>[],maximum:2000})
const emit=defineEmits<{(e:'update:modelValue',value:any):void}>()
function changed(event:any){const value=event.detail.value;if(props.type==='integer'){emit('update:modelValue',value===''?null:Number(value))}else emit('update:modelValue',value)}
function switchChanged(event:any){emit('update:modelValue',event.detail.value)}
function select(event:any){emit('update:modelValue',props.options[Number(event.detail.value)]?.value)}
function toggle(value:string){const current:Array<string>=Array.isArray(props.modelValue)?props.modelValue:[];emit('update:modelValue',current.includes(value)?current.filter(v=>v!==value):[...current,value])}
</script>
<template><FormField :label="label" :hint="hint" :error="error" :required="required" :readonly="disabled"><picker v-if="type==='select'" :range="options" range-key="label" :disabled="disabled" @change="select"><view class="s1-picker">{{options.find(o=>o.value===modelValue)?.label||'请选择'}}<text>⌄</text></view></picker><view v-else-if="type==='multi'" class="s1-options"><view v-for="option in options" :key="option.value" class="s1-option" :class="{'s1-option--selected':(modelValue||[]).includes(option.value)}" @click="!disabled&&toggle(option.value)"><text>{{(modelValue||[]).includes(option.value)?'✓':'○'}} {{option.label}}</text></view><text v-if="!options.length">暂无可选项</text></view><switch v-else-if="type==='boolean'" :checked="!!modelValue" :disabled="disabled" color="#1B4D53" @change="switchChanged"/><textarea v-else-if="type==='textarea'" :value="modelValue||''" :disabled="disabled" :maxlength="maximum" auto-height :cursor-spacing="80" @input="changed"/><picker v-else-if="type==='date'" mode="date" :value="modelValue||''" :disabled="disabled" @change="changed"><view class="s1-picker">{{modelValue||'请选择日期'}}<text>⌄</text></view></picker><input v-else :value="modelValue==null?'':String(modelValue)" :type="type==='integer'?'number':type==='money'?'digit':'text'" :disabled="disabled" :maxlength="maximum" :cursor-spacing="80" @input="changed"/></FormField></template>
<style scoped lang="scss">.s1-picker{display:flex;justify-content:space-between;align-items:center;min-height:48px;font-size:15px}.s1-options{display:flex;flex-wrap:wrap;gap:$space-2;padding:$space-2 0}.s1-option{display:flex;align-items:center;min-height:$touch-target-min;padding:0 $space-2;color:$color-text-secondary}.s1-option--selected{color:$color-primary;font-weight:600}switch{margin:8px 0}textarea{min-height:92px;width:100%;line-height:1.6}</style>
